package com.diberlog.jarvis.mobile;

import android.app.*;
import android.content.*;
import android.os.Build;
import org.json.*;
import java.time.*;
import java.util.*;

public final class ReminderReceiver extends BroadcastReceiver {
    static long before(long due,int days){return Instant.ofEpochMilli(due).atZone(ZoneId.systemDefault()).minusDays(days).toInstant().toEpochMilli();}
    static final String CHANNEL="jarvis-reminders";
    static void channels(Context c){NotificationChannel channel=new NotificationChannel(CHANNEL,"Напоминания и таймер",NotificationManager.IMPORTANCE_HIGH);channel.enableVibration(true);channel.setDescription("Напоминания, дни рождения и завершение таймеров");c.getSystemService(NotificationManager.class).createNotificationChannel(channel);}
    static boolean enabled(Context c){channels(c);NotificationManager manager=c.getSystemService(NotificationManager.class);NotificationChannel channel=manager.getNotificationChannel(CHANNEL);return manager.areNotificationsEnabled()&&channel!=null&&channel.getImportance()!=NotificationManager.IMPORTANCE_NONE;}
    static long millis(String value){try{return Instant.parse(value).toEpochMilli();}catch(Exception e){return LocalDateTime.parse(value).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();}}
    static PendingIntent pending(Context c,String id,String title,long when,String record,int lead){Intent i=new Intent(c,ReminderReceiver.class).setAction("jarvis."+id).putExtra("id",id).putExtra("title",title).putExtra("when",when).putExtra("record",record).putExtra("lead",lead);return PendingIntent.getBroadcast(c,id.hashCode(),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
    static void alarm(Context c,String id,String title,long when){alarm(c,id,title,when,"",0);}
    static void alarm(Context c,String id,String title,long when,String record,int lead){if(when<=System.currentTimeMillis())return;AlarmManager a=c.getSystemService(AlarmManager.class);PendingIntent p=pending(c,id,title,when,record,lead);try{if(Build.VERSION.SDK_INT<31||a.canScheduleExactAlarms())a.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,p);else a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,p);}catch(SecurityException permissionChanged){a.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,p);}}
    static void cancel(Context c,String id){c.getSystemService(AlarmManager.class).cancel(pending(c,id,"",0,"",0));}
    static final class Event{final String id,title,record;final long when;final int lead;Event(String id,String title,long when,String record,int lead){this.id=id;this.title=title;this.when=when;this.record=record;this.lead=lead;}}
    static java.util.List<Event> events(JSONObject data,long now)throws Exception{List<Event> events=new ArrayList<>();JSONArray reminders=data.getJSONArray("reminders");for(int n=0;n<reminders.length();n++){JSONObject r=reminders.getJSONObject(n);if(r.optBoolean("done"))continue;long due=millis(r.getString("dueAt"));String record=r.getString("id"),title=r.getString("title");if(due>now||!r.optBoolean("silentPast")&&now-due<=72*3600000L)events.add(new Event("reminder-"+record,title,due,record,0));JSONArray advance=r.optJSONArray("advanceDays");Set<Integer> seen=new HashSet<>();if(advance!=null)for(int j=0;j<advance.length();j++){int days=advance.getInt(j);if(days<1||days>365||!seen.add(days))continue;long before=before(due,days);if(before>now)events.add(new Event("reminder-"+record+"-before-"+days,"Через "+days+" дн.: "+title,before,record,days));}}
        JSONArray birthdays=data.getJSONArray("birthdays");for(int n=0;n<birthdays.length();n++){JSONObject b=birthdays.getJSONObject(n);LocalDate today=Instant.ofEpochMilli(now).atZone(ZoneId.systemDefault()).toLocalDate();int year=Math.max(today.getYear(),b.optInt("year",today.getYear()));LocalDate date=birthday(year,b.getInt("month"),b.getInt("day"));if(date.atTime(9,0).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli()<=now)date=birthday(year+1,b.getInt("month"),b.getInt("day"));events.add(new Event("birthday-"+b.getString("id"),"День рождения: "+b.getString("name"),date.atTime(9,0).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli(),b.getString("id"),0));}
        events.sort(Comparator.comparingLong(e->e.when));return events;}
    static synchronized void schedule(Context c){channels(c);android.content.SharedPreferences prefs=MobileStore.prefs(c);try{
        long now=System.currentTimeMillis();List<Event> desired=events(MobileStore.center(c),now);JSONArray previous=new JSONArray(prefs.getString("scheduled","[]"));for(int i=0;i<previous.length();i++)cancel(c,previous.getString(i));JSONArray ids=new JSONArray();int future=0,missed=0;
        for(Event event:desired){if(event.when>now){if(future++>=450)continue;alarm(c,event.id,event.title,event.when,event.record,event.lead);ids.put(event.id);}else if(missed++<20)deliver(c,event.id,event.title,event.when,event.record,event.lead);}
        long timer=prefs.getLong("timerEnd",0);if(timer>now)alarm(c,"timer","Таймер завершён",timer);
        JSONObject rest=SyncJournal.snapshot(c).optJSONObject("training_timer");if(rest!=null&&rest.optString("phase").equals("running")&&!rest.isNull("deadline")&&rest.getLong("deadline")>now)alarm(c,"training-rest",rest.optString("label","Отдых завершён"),rest.getLong("deadline"));
        prefs.edit().putString("scheduled",ids.toString()).putString("reminderScheduleError",future>450?"Запланированы ближайшие 450 сигналов; остальные будут добавляться после срабатывания.":"").apply();
    }catch(Exception e){prefs.edit().putString("reminderScheduleError","Не удалось перепланировать сигналы. Проверьте даты записей; данные и прежние сигналы сохранены.").apply();}}
    static LocalDate birthday(int year,int month,int day){try{return LocalDate.of(year,month,day);}catch(DateTimeException e){if(month==2&&day==29)return LocalDate.of(year,3,1);throw e;}}
    static JSONObject currentReminder(Context c,String record,long when,int lead)throws Exception{JSONArray reminders=MobileStore.center(c).getJSONArray("reminders");for(int n=0;n<reminders.length();n++){JSONObject r=reminders.getJSONObject(n);if(r.optString("id").equals(record)&&!r.optBoolean("done")&&before(millis(r.getString("dueAt")),lead)==when){if(lead>0){JSONArray advance=r.optJSONArray("advanceDays");boolean found=false;if(advance!=null)for(int j=0;j<advance.length();j++)if(advance.optInt(j)==lead)found=true;if(!found)return null;}return r;}}return null;}
    static void deliver(Context c,String id,String title,long when,String record,int lead)throws Exception{if(!enabled(c))return;android.content.SharedPreferences prefs=MobileStore.prefs(c);String delivered="delivered."+id; if(prefs.getLong(delivered,-1)==when)return;
        Intent open=new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP).setAction("jarvis.open."+id).putExtra("section",id.startsWith("birthday-")?7:id.startsWith("reminder-")?6: id.equals("training-rest")?10:5);
        PendingIntent launch=PendingIntent.getActivity(c,id.hashCode(),open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
        Notification.Builder note=new Notification.Builder(c,CHANNEL).setSmallIcon(com.diberlog.jarvis.mobile.R.drawable.ic_bell).setContentTitle(id.equals("timer")||id.equals("training-rest")?"Время вышло":"JARVIS · напоминание").setContentText(title).setStyle(new Notification.BigTextStyle().bigText(title)).setCategory(Notification.CATEGORY_REMINDER).setVisibility(Notification.VISIBILITY_PRIVATE).setWhen(when).setAutoCancel(true).setContentIntent(launch);
        if(id.startsWith("reminder-")){Intent done=new Intent(c,ReminderReceiver.class).setAction("jarvis.done."+id).putExtra("id",id).putExtra("record",record).putExtra("lead",lead).putExtra("when",when).putExtra("done",true);PendingIntent action=PendingIntent.getBroadcast(c,id.hashCode(),done,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);note.addAction(new Notification.Action.Builder(android.graphics.drawable.Icon.createWithResource(c,R.drawable.ic_check),"Выполнено",action).build());}
        try{c.getSystemService(NotificationManager.class).notify(id,id.hashCode(),note.build());prefs.edit().putLong(delivered,when).apply();}catch(SecurityException ignored){prefs.edit().putString("reminderScheduleError","Разрешите уведомления для JARVIS в настройках Android.").apply();}}
    void fire(Context c,Intent intent){try{String id=intent.getStringExtra("id");if(id==null)return;long when=intent.getLongExtra("when",0);if(when<=0||when>System.currentTimeMillis()+2000)return;String record=intent.getStringExtra("record"),title=intent.getStringExtra("title");int lead=intent.getIntExtra("lead",0);if(lead<0||lead>365)return;
        if(id.startsWith("reminder-")){JSONObject r=currentReminder(c,record,when,lead);if(r==null)return;title=lead==0?r.getString("title"):"Через "+lead+" дн.: "+r.getString("title");if(intent.getBooleanExtra("done",false)){JSONObject data=MobileStore.editCenter(c,r);JSONArray reminders=data.getJSONArray("reminders");for(int n=0;n<reminders.length();n++)if(reminders.getJSONObject(n).optString("id").equals(record))reminders.getJSONObject(n).put("done",true);MobileStore.save(c,data);c.getSystemService(NotificationManager.class).cancel(id,id.hashCode());return;}}
        else if(id.equals("timer")){if(MobileStore.prefs(c).getLong("timerEnd",0)!=when)return;MobileStore.prefs(c).edit().putLong("timerEnd",0).apply();}
        else if(id.equals("training-rest")){JSONObject rest=SyncJournal.snapshot(c).optJSONObject("training_timer");if(rest==null||!rest.optString("phase").equals("running")||rest.optLong("deadline")!=when)return;title="Отдых завершён · "+rest.optString("label","Тренировка");rest.put("phase","finished").put("remaining",0).put("deadline",JSONObject.NULL);SyncJournal.save(c,"training_timer",rest);}
        else if(id.startsWith("birthday-")){JSONArray list=MobileStore.center(c).getJSONArray("birthdays");boolean found=false;for(int n=0;n<list.length();n++)if(list.getJSONObject(n).optString("id").equals(record)){JSONObject entry=list.getJSONObject(n);int year=Instant.ofEpochMilli(when).atZone(ZoneId.systemDefault()).getYear();long expected=birthday(year,entry.getInt("month"),entry.getInt("day")).atTime(9,0).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();if(expected!=when||year<entry.optInt("year",year))return;title="День рождения: "+list.getJSONObject(n).getString("name");found=true;}if(!found)return;}
        else return;deliver(c,id,title==null?"Напоминание":title,when,record,lead);schedule(c);
    }catch(Exception ignored){MobileStore.prefs(c).edit().putString("reminderScheduleError","Сигнал не показан: запись изменилась или повреждена. Исходные данные сохранены.").apply();}}
    @Override public void onReceive(Context c,Intent intent){PendingResult result=goAsync();new Thread(()->{try{fire(c,intent);}finally{if(result!=null)result.finish();}},"jarvis-reminder").start();}
}
